sidebarSymbols.push('<path d="M3 3v18h18M7 16v-4M12 16V7M17 16v-6"/>','<path d="M3 6h7l2 2h9v12H3zM7 13h10M7 16h6"/>');
for(const [aud,title,desc,out] of [['Finance & executive leadership','See performance against the plan.','Bring financial actuals, plan, forecast, and prior-year results into one explainable view.','Financial metrics + variance drivers + management commentary'],['Leadership & delivery teams','Make the case. Track the investment.','Bring proposed applications, investment assumptions, delivery stages, and accountable owners into one portfolio.','Business cases + investment assumptions + delivery stages']])productStories.push({audience:aud,title,desc,output:out});
showcaseMeta.push(['Explore financial performance','Financial performance','Actual vs plan','Prior-year comparisons','Metric drill-down',0],['Explore business cases','Investment portfolio','Case evaluation','Delivery stages','Portfolio visibility',0]);
studioProductDetails.push(['Financial performance with the context behind it.','Give leadership a shared view of revenue, bookings, EBITDA, headcount, and cash—with comparisons that make the variance visible and a direct path into its drivers.',[['Read the scorecard','Review the selected snapshot against the operating plan or forecast.'],['Explain the movement','Drill into financial metrics, compare prior periods, and separate favorable from unfavorable variance.'],['Prepare the discussion','Use AI-assisted commentary to frame the questions and decisions for the next leadership review.']],['Claude API and OpenAI API can explain movements, summarize financial context, and draft management commentary for review.','Connect SharePoint reporting packs and coordinate finance reviews through Microsoft Teams.','Model financial snapshots in Supabase, deliver reporting through Vercel, and connect enterprise sources with Azure as required.']],['A clear investment case for every application.','Give executives and delivery teams one workspace to evaluate opportunities, review assumptions, and follow each application from proposed idea through delivery and iteration.',[['Build the case','Capture the workflow problem, investment estimate, expected benefit, and accountable owner.'],['Review the assumptions','Examine the business rationale, calculation inputs, dependencies, and evidence before deciding.'],['Track the portfolio','Group cases by stage, owner, or business track and inspect the next decision for each.']],['Use Claude API and OpenAI API to challenge assumptions, draft case narratives, and summarize portfolio priorities.','Keep supporting material in SharePoint and connect stakeholder reviews through Microsoft Teams.','Store case history and investment inputs in Supabase, present the register through Vercel, and use Azure for client-specific connections.']]);
