intelligenceProfiles.push(['Finance performance copilot',['Explain the financial variances','Draft a management commentary','Model financial-review time'],'Illustrative financial scorecard · operating plan · forecast','Compare actuals with the selected basis, inspect the material movements, and verify the source period. Favorability depends on the metric: lower cost may help margin while lower revenue does not.','Management commentary\nRevenue should be reviewed alongside bookings, delivery capacity, and cash. Identify material variances, validate the underlying drivers, and assign the follow-up decisions before circulating the report.',2,'finance reviews',12,120],['Business case copilot',['Review investment priorities','Draft an investment recommendation','Model case-review time'],'Illustrative application investment register','Compare benefit assumptions and build plus recurring costs. Keep proposals, forecast benefits, and demonstrated results separate. Stage changes are illustrative and do not represent deployment evidence.','Investment recommendation\nValidate the baseline workflow, estimated adoption, complete cost, and accountable owner. Prioritize cases with a clear problem and evidence for the benefit, then define an acceptance checkpoint.',2,'investment reviews',20,90]);
let financeCompare='Plan',financeSnapshot='September 2026';
const financeMetrics=[['Net revenue',24800,25200,24550,23100,'$K',1],['New bookings',5200,6400,5600,5900,'$K',1],['EBITDA',2780,3050,2840,2180,'$K',1],['Headcount',168,174,170,172,'FTE',-1],['Revenue / headcount',147.6,144.8,144.4,134.3,'$K',1],['Labor / net revenue',61.8,62.5,62.2,64.1,'%',-1],['Gross revenue',47600,47000,47250,43800,'$K',1],['Cash position',4250,3900,4100,3100,'$K',1]];
function financeFactor(){return financeSnapshot==='August 2026'?.89:financeSnapshot==='July 2026'?.78:1}
function financeVal(v,unit){return unit==='%'?v.toFixed(1)+'%':unit==='FTE'?Math.round(v).toLocaleString():v.toLocaleString('en-US',{maximumFractionDigits:1})}
function financeValues(i){const m=financeMetrics[i],f=m[5]==='FTE'||m[5]==='%'||i===4?1:financeFactor();return {m,actual:m[1]*f,compare:m[financeCompare==='Plan'?2:3]*f,prior:m[4]*f}}
function financeDelta(a,b,unit,direction){const delta=a-b,favorable=delta*direction>=0;return `<span class="finance-delta ${Math.abs(delta)<.01?'neutral':favorable?'favorable':'unfavorable'}">${delta>0?'+':''}${unit==='%'?delta.toFixed(1)+' pp':financeVal(delta,unit)}</span>`}
function financeControls(){return `<div class="finance-controls"><span>COMPARE TO</span>${['Plan','Forecast'].map(b=>`<button class="${financeCompare===b?'active':''}" onclick="financeCompare='${b}';render()">${b}</button>`).join('')}<label>Snapshot <select onchange="financeSnapshot=this.value;render()">${['July 2026','August 2026','September 2026'].map(x=>`<option ${x===financeSnapshot?'selected':''}>${x}</option>`).join('')}</select></label></div>`}
function financeMetric(i){const {m,actual,compare,prior}=financeValues(i);return `<button class="finance-scorecard" onclick="financeDetail(${i})"><div class="finance-scorecard-label"><h3>${m[0]}</h3><span>${m[5]}</span></div><div class="finance-scorecard-value"><strong>${financeVal(actual,m[5])}</strong><small>${financeSnapshot} · YTD${['FTE','%'].includes(m[5])?' snapshot':''}</small></div><div class="finance-comparison"><span>VS ${financeCompare.toUpperCase()}</span><b>${financeVal(compare,m[5])}</b>${financeDelta(actual,compare,m[5],m[6])}</div><div class="finance-comparison"><span>VS PRIOR YEAR</span><b>${financeVal(prior,m[5])}</b>${financeDelta(actual,prior,m[5],m[6])}</div><div class="finance-card-bottom">Inspect variance ${icon('arrow')}</div></button>`}
function financeGuide(){draw('Financial scorecard methodology',`<p>All figures are illustrative. Monetary scorecard values are shown in $K, headcount in FTE, and ratios in percent.</p><p>The selected snapshot changes sample monetary totals. Headcount and ratios are snapshot values. Comparisons use the selected Plan or Forecast basis.</p><p>Revenue, bookings, EBITDA, productivity, and cash favor higher values. Headcount and labor ratio favor lower values for this sample plan; lower staffing is not always operationally better.</p><p>Variance is actual minus comparison. Ratio differences are percentage points. The prior-year comparison uses the same illustrative period.</p>`)}
function financeDetail(i){const {m,actual,compare,prior}=financeValues(i);draw(m[0]+' · variance detail',`<div class="finance-detail-total"><span>${financeSnapshot} · ${m[5]}</span><strong>${financeVal(actual,m[5])}</strong>${financeDelta(actual,compare,m[5],m[6])}</div>${table(['Comparison','Value','Variance'],[[financeCompare,financeVal(compare,m[5]),financeDelta(actual,compare,m[5],m[6])],['Prior year',financeVal(prior,m[5]),financeDelta(actual,prior,m[5],m[6])]])}<h3>Questions for the review</h3><p>${['Which accounts and timing differences explain the revenue change? Confirm recognized revenue against the source ledger.','Are bookings below target because of volume, deal size, or timing? Review the pipeline evidence before changing the outlook.','Separate revenue contribution from labor, operating cost, and timing effects. Confirm whether the movement is recurring.','Is the staffing difference consistent with delivery commitments and the capacity plan? Lower headcount is not automatically beneficial.','Check utilization, revenue timing, and whether the staffing denominator matches the reporting period.','Check staffing mix, utilization, and the revenue denominator before interpreting a lower ratio.','Compare net revenue with pass-through and other revenue before interpreting top-line growth.','Review collections, payment timing, commitments, and working capital before treating cash growth as recurring.'][i]}</p>${ib('Generate finance commentary','intelligenceOpen(14,1)','spark','primary')}`)}
function financialDashboard(){const selected=JSON.parse(localStorage.getItem('nine67-finance-metrics')||'[0,1,2,7]');return `<div class="experience finance-product">${expHeader(14,ib('AI commentary','intelligenceOpen(14,0)','spark','primary'),ib('Methodology','financeGuide()','help'))}<div class="finance-body"><div class="finance-title"><div><span class="micro-label">FINANCIAL PLANNING & ANALYSIS</span><h1>${tab===1?'My financial dashboard':tab===2?'Variance analysis':'Financial performance'}</h1><p>Actuals, expectations, and the reasons behind the movement.</p></div>${financeControls()}</div>${tab===1?`<div class="finance-metric-picker"><span>Choose your metrics</span>${financeMetrics.map((m,i)=>`<button class="${selected.includes(i)?'active':''}" onclick="financePick(${i})">${m[0]}</button>`).join('')}</div>`:''}${tab<2?`<div class="finance-metrics-grid">${(tab===1?selected:financeMetrics.map((_,i)=>i)).map(financeMetric).join('')}</div>`:`<div class="finance-variance-register">${table(['Metric','Actual',financeCompare,'Variance','Direction',''],financeMetrics.map((m,i)=>{const v=financeValues(i);return [m[0],financeVal(v.actual,m[5]),financeVal(v.compare,m[5]),financeDelta(v.actual,v.compare,m[5],m[6]),m[6]===1?'Higher favorable':'Lower favorable',ib('Detail',`financeDetail(${i})`,'arrow','link')]}))}</div>`}<p class="finance-note">Sample financial data · $K unless otherwise labeled · Green is favorable to the selected comparison · Red is unfavorable</p></div></div>`}
function financePick(i){let a=JSON.parse(localStorage.getItem('nine67-finance-metrics')||'[0,1,2,7]');a=a.includes(i)?a.filter(v=>v!==i):[...a,i];localStorage.setItem('nine67-finance-metrics',JSON.stringify(a));render()}
const financialDrivers={attrition:4,labor:3,opex:3,cogs:46,renewal:92,bookings:6,target:5};
function financialModel(){const d=financialDrivers,base=31.8,retained=base*(1-d.attrition/100),renewal=3*d.renewal/100,newRev=d.bookings*.55,revenue=retained+renewal+newRev,direct=revenue*d.cogs/100,labor=12.8*(1+d.labor/100),overhead=3.8*(1+d.opex/100),commission=d.bookings*.08,ebitda=revenue-direct-labor-overhead-commission;return {base,retained,renewal,newRev,revenue,direct,labor,overhead,commission,ebitda,margin:ebitda/revenue*100}}
function financialDriver(label,key,min,max,step,unit){return `<label class="financial-lever"><span>${label}<output id="lever-${key}">${financialDrivers[key]}${unit}</output></span><input aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${financialDrivers[key]}" oninput="financialSet('${key}',this.value,'${unit}')"></label>`}
function financialSet(k,v,u){financialDrivers[k]=Number(v);$('#lever-'+k).textContent=v+u;financialRefresh()}
function financialSummary(){const m=financialModel();return `<div class="financial-model-kpis">${[['Rolling-12 net revenue',m.revenue,'$M'],['Rolling-12 EBITDA',m.ebitda,'$M'],['EBITDA margin',m.margin,'%'],['New net bookings',financialDrivers.bookings,'$M']].map(([l,v,u])=>`<div><span>${l}</span><b>${u==='$M'?'$':''}${v.toFixed(u==='%'?1:2)}${u==='$M'?'M':'%'}</b></div>`).join('')}</div>`}
function financialBridge(){const m=financialModel(),d=financialDrivers,gap=d.target-m.ebitda,incrementalMargin=1-d.cogs/100-.08/.55,needed=gap>0&&incrementalMargin>0?gap/(.55*incrementalMargin):0;return `<div class="financial-bridge-grid"><section><span>MODEL BUILD-UP</span><h3>Revenue to EBITDA</h3>${[['Committed after attrition',m.retained],['Renewal revenue',m.renewal],['New bookings recognized',m.newRev],['Direct costs',-m.direct],['Labor cost',-m.labor],['Operating cost',-m.overhead],['Sales commissions',-m.commission]].map(([l,v])=>`<div><span>${l}</span><b class="${v<0?'negative':'positive'}">${v<0?'−':'+'}$${Math.abs(v).toFixed(2)}M</b></div>`).join('')}<footer>Rolling EBITDA <b>$${m.ebitda.toFixed(2)}M</b></footer></section><section><span>TARGET SCENARIO</span><h3>Path to $${d.target.toFixed(1)}M EBITDA</h3><p>${gap>0?'Gap to close: $'+gap.toFixed(2)+'M':'Target met in this illustrative model.'}</p><div class="financial-target-result"><small>Additional bookings needed, with all other inputs fixed</small><strong>$${needed.toFixed(2)}M</strong></div><p class="finance-note">55% recognition, ${d.cogs}% direct cost on revenue, and 8% commission on bookings. This isolates the bookings lever; it is not a sales forecast.</p><button onclick="financialReset()">Reset assumptions</button></section></div>`}
function financialTable(){const m=financialModel(),months=['Nov','Dec','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct'],weights=[.075,.065,.07,.075,.08,.08,.085,.09,.09,.095,.095,.1];return `<div class="financial-table-scroll"><table class="financial-pnl"><thead><tr><th>Rolling 12 · $K</th>${months.map(x=>`<th>${x}</th>`).join('')}<th>Total</th></tr></thead><tbody>${[['Net revenue',m.revenue],['Direct costs',-m.direct],['Labor',-m.labor],['Operating costs',-m.overhead],['Commissions',-m.commission],['EBITDA',m.ebitda]].map(([l,v])=>`<tr><th>${l}</th>${weights.map(w=>`<td>${Math.round(v*1000*w).toLocaleString()}</td>`).join('')}<td><b>${Math.round(v*1000).toLocaleString()}</b></td></tr>`).join('')}</tbody></table></div>`}
function financialRefresh(){$('#financialSummary').innerHTML=financialSummary();$('#financialBridge').innerHTML=financialBridge();$('#financialPnl').innerHTML=financialTable()}
function financialReset(){Object.assign(financialDrivers,{attrition:4,labor:3,opex:3,cogs:46,renewal:92,bookings:6,target:5});render()}
function financialPlanning(){return `<div class="experience forecast-product financial-planning">${expHeader(9,ib('AI scenario narrative','intelligenceOpen(9,0)','spark','primary'),ib('Methodology','financialMethod()','help'))}<div class="finance-body"><div class="finance-title"><div><span class="micro-label">ROLLING-12 FINANCIAL MODEL</span><h1>Change the assumptions. See the financial effect.</h1><p>Revenue, cost, and EBITDA update together as you adjust the model.</p></div></div><div id="financialSummary">${financialSummary()}</div><div class="financial-planning-grid"><aside><h2>Financial levers</h2>${financialDriver('Attrition','attrition',0,20,.5,'%')}${financialDriver('Labor inflation','labor',-15,15,.5,'%')}${financialDriver('Operating cost inflation','opex',-15,15,.5,'%')}${financialDriver('Direct cost / revenue','cogs',30,65,.5,'%')}${financialDriver('Renewal realization','renewal',50,100,1,'%')}${financialDriver('New bookings','bookings',0,20,.5,'M')}${financialDriver('EBITDA target','target',1,10,.5,'M')}</aside><div><h2>EBITDA bridge & target path</h2><div id="financialBridge">${financialBridge()}</div><h2 class="financial-pnl-title">Monthly P&L</h2><div id="financialPnl">${financialTable()}</div></div></div><p class="finance-note">Illustrative model · Deterministic calculations · Monthly values are allocated from annual totals using sample seasonal weights · Rounding may differ by $1K</p></div></div>`}
function financialMethod(){draw('Financial model assumptions',`<p>All inputs and outputs are illustrative and shown in $M unless the monthly P&L labels $K.</p><p>Net revenue = $31.8M committed × (1 − attrition) + $3M renewal opportunity × realization + new bookings × 55% recognized.</p><p>EBITDA = net revenue − direct costs − $12.8M labor × inflation factor − $3.8M operating costs × inflation factor − 8% of bookings in commissions.</p><p>The target path isolates additional bookings while fixing the other assumptions. Each incremental $1M of bookings contributes 55% × (1 − direct-cost ratio) − 8% to modeled EBITDA.</p><p>Monthly figures distribute the totals with seasonal weights summing to 100%; they are not account-level revenue recognition schedules.</p>`)}
expMenu[9].push('Financial planning');const forecastBeforeFinancialPlanning=forecastExperience;forecastExperience=function(){return tab===3?financialPlanning():forecastBeforeFinancialPlanning()};
const caseStages=['Proposed','In development','Testing & review','Live & iteration'];let caseGroup='stage';
let businessCaseRecords=JSON.parse(localStorage.getItem('nine67-business-cases')||'null')||toolsList.slice(0,14).map((t,i)=>({id:i,title:t[0],stage:caseStages[i%4],owner:['Alex Morgan','Taylor Kim','Jordan Ellis'][i%3],track:t[2],build:45000+i*2500,running:7200,benefit:90000+i*8000,problem:clientValue[i][1],outcome:clientValue[i][2]}));
function caseSave(){localStorage.setItem('nine67-business-cases',JSON.stringify(businessCaseRecords))}
function caseRecord(id){const c=businessCaseRecords.find(x=>x.id===id);draw(c.title,`<span class="micro-label">ILLUSTRATIVE BUSINESS CASE</span><p>${esc(c.problem)}</p><h3>Expected outcome</h3><p>${esc(c.outcome)}</p><div class="case-financials"><div><small>Build estimate</small><b>${money(c.build)}</b></div><div><small>Annual benefit assumption</small><b>${money(c.benefit)}</b></div><div><small>Year-one modeled ROI</small><b>${Math.round((c.benefit-c.running-c.build)/c.build*100)}%</b></div></div><p class="finance-note">Benefit is an assumption, not a demonstrated result. Annual recurring cost: ${money(c.running)}.</p><label class="health-label">Delivery stage<select id="caseStage">${caseStages.map(s=>`<option ${s===c.stage?'selected':''}>${s}</option>`).join('')}</select></label><label class="health-label">Accountable owner<select id="caseOwner">${['Alex Morgan','Taylor Kim','Jordan Ellis'].map(s=>`<option ${s===c.owner?'selected':''}>${s}</option>`).join('')}</select></label>${ib('Save case update',`caseUpdate(${id})`,'check','primary')}${ib('AI investment review','intelligenceOpen(15,0)','spark')}<p class="finance-note">Stage changes are local demo edits, not evidence of a real deployment.</p>`)}
function caseUpdate(id){const c=businessCaseRecords.find(x=>x.id===id);c.stage=$('#caseStage').value;c.owner=$('#caseOwner').value;caseSave();closeDrawer();render();toast('Demo case updated')}
function caseNew(){draw('New business case',`<label class="health-label">Application name<input id="caseTitle" placeholder="e.g. Service request assistant"></label><label class="health-label">Workflow problem<textarea id="caseProblem"></textarea></label><label class="health-label">Expected outcome<textarea id="caseOutcome"></textarea></label><label class="health-label">Build estimate · $<input id="caseBuild" type="number" min="1" value="45000"></label><label class="health-label">Annual benefit assumption · $<input id="caseBenefit" type="number" min="0" value="90000"></label><label class="health-label">Annual recurring cost · $<input id="caseRunning" type="number" min="0" value="7200"></label>${ib('Create demo case','caseCreate()','plus','primary')}<p class="finance-note">Saved in this browser only. No approval request is sent.</p>`)}
function caseCreate(){const title=$('#caseTitle').value.trim(),build=Number($('#caseBuild').value),benefit=Number($('#caseBenefit').value),running=Number($('#caseRunning').value);if(!title||build<=0||benefit<0||running<0){toast('Add a name and valid nonnegative estimates');return}businessCaseRecords.push({id:Date.now(),title,stage:'Proposed',owner:'Alex Morgan',track:'Planning',build,benefit,running,problem:$('#caseProblem').value.trim(),outcome:$('#caseOutcome').value.trim()});caseSave();closeDrawer();render()}
function caseBoard(){const groups=caseGroup==='stage'?caseStages:[...new Set(businessCaseRecords.map(c=>c[caseGroup]))];return `<div class="case-board">${groups.map(g=>`<section class="case-column"><h2>${g}<span>${businessCaseRecords.filter(c=>c[caseGroup]===g).length}</span></h2>${businessCaseRecords.filter(c=>c[caseGroup]===g).map(c=>`<button class="case-tile" onclick="caseRecord(${c.id})"><span>${c.stage}</span><h3>${esc(c.title)}</h3><p>${esc(c.owner)} · ${c.track}</p><div><b>${money(c.build)}</b><small>build estimate</small>${icon('arrow')}</div></button>`).join('')}</section>`).join('')}</div>`}
function businessCasesExperience(){const build=businessCaseRecords.reduce((s,c)=>s+c.build,0),benefit=businessCaseRecords.reduce((s,c)=>s+c.benefit,0),running=businessCaseRecords.reduce((s,c)=>s+c.running,0);return `<div class="experience cases-product">${expHeader(15,ib('New case','caseNew()','plus','primary'),ib('AI portfolio review','intelligenceOpen(15,0)','spark'))}<div class="finance-body"><div class="finance-title"><div><span class="micro-label">APPLICATION INVESTMENT PORTFOLIO</span><h1>${expMenu[15][tab]}</h1><p>Every case has a rationale, an accountable owner, and a next decision.</p></div></div>${tab===0?`<div class="case-group-controls"><span>GROUP BY</span>${[['stage','Stage'],['owner','Owner'],['track','Business track']].map(([k,l])=>`<button class="${caseGroup===k?'active':''}" onclick="caseGroup='${k}';render()">${l}</button>`).join('')}</div>${caseBoard()}`:tab===1?table(['Business case','Stage','Owner','Build estimate','Annual benefit assumption',''],businessCaseRecords.map(c=>[esc(c.title),c.stage,c.owner,money(c.build),money(c.benefit),ib('Open',`caseRecord(${c.id})`,'arrow','link')])):`<div class="financial-model-kpis">${[['Cases',businessCaseRecords.length],['Combined build estimate',money(build)],['Assumed annual benefits',money(benefit)],['Modeled year-one net',money(benefit-running-build)]].map(([h,v])=>`<div><span>${h}</span><b>${v}</b></div>`).join('')}</div><div class="finance-analysis-note"><h2>Review the assumptions before ranking the cases.</h2><p>Portfolio totals add the entered estimates. They do not adjust for overlapping benefits, delivery capacity, adoption delays, or uncertainty. Review the individual cases and avoid double-counting shared benefits.</p>${ib('Prepare investment commentary','intelligenceOpen(15,1)','spark','primary')}</div>`}<p class="finance-note">Sample investment cases and illustrative stages · Local demo edits only · No client or production deployment status represented</p></div></div>`}
function registerExtendedApp(name,group,description,audience,headline,steps,technology,technologyHeadings,value,profile,svg){const id=toolsList.length;toolsList.push([name,'',group,description]);productIcons.push(id===16?'roi':'sales');expNames.push(name);expLabels.push(id===16?'ENTERPRISE VALUE MODEL':'CLIENT ECONOMICS');expMenu.push(id===16?['Value thesis','Value model','Assumptions & evidence']:['Profitability dashboard','Client watch','Executive summary']);studioGroups[group].push(id);sidebarSymbols.push(svg);productStories.push({audience,title:headline,desc:description,output:id===16?'Operating uplift + value scenarios + assumption review':'Client margin + contribution + account actions'});showcaseMeta.push(['Explore '+name.toLowerCase(),name,...value[4],0]);studioProductDetails.push([headline,description,steps,technology]);studioTechnologyHeadings.push(technologyHeadings);clientValue.push(value);intelligenceProfiles.push(profile)}
registerExtendedApp('Impact OS','Planning','Connect application adoption, operating improvements, and investment assumptions in an explainable enterprise-value model.','Executives & operating leaders','Measure the operating lift. Understand the value assumptions.',[['Frame the opportunity','Identify the operational change and the evidence needed to establish a baseline.'],['Model the value','Adjust adoption, capacity released, cost, and valuation assumptions with the calculation visible.'],['Review the evidence','Separate validated inputs, hypotheses, and realized results before making investment decisions.']],['Claude API and OpenAI API can challenge value assumptions and draft investment narratives.','Connect business-case evidence in SharePoint and leadership reviews in Microsoft Teams.','Supabase holds model assumptions and evidence records; Vercel and Azure support the selected application environment.'],['Value reasoning & assumption review','Operating evidence & leadership discussion','Value models & measurement records'],['Measure value beyond the demo','Applications can create activity without a clear baseline or an agreed view of their economic impact.','A transparent operating-value model connects adoption, cost, and business assumptions to a reviewable scenario.','Connect operating change to modeled value',['Operating baseline','Value assumptions','Evidence review']],['Impact copilot',['Challenge the value assumptions','Draft an operating-value thesis','Model value-review preparation time'],'Illustrative operating model · explicit valuation assumptions','Separate gross capacity released from cash savings and avoid counting the same benefit twice. A valuation multiple is a scenario assumption, not an appraisal.','Operating-value thesis\nDefine the workflow and its current cost. Validate adoption, time released, and any additional costs. Distinguish expected operating benefit from observed results, then review valuation sensitivity separately.',1,'value reviews',12,90],'<circle cx="12" cy="12" r="9"/><path d="m6 14 4-5 4 3 4-6"/>');
registerExtendedApp('Client Profitability','Delivery','Analyze account revenue, delivery cost, contribution, and margin so teams can identify which client relationships need a commercial or delivery review.','Finance, account & delivery leaders','Understand which relationships create sustainable value.',[['See account economics','Review net revenue, direct labor, contribution, and effective rate by client.'],['Investigate the pressure','Filter by business area and owner, then inspect the account-level cost and delivery context.'],['Test a better plan','Explore price and labor assumptions before agreeing on the next commercial action.']],['Claude API and OpenAI API can explain account economics and draft profitability review notes.','Reference account reviews and supporting schedules in SharePoint and coordinate actions in Microsoft Teams.','Supabase stores account-level financial snapshots, with Vercel for delivery and Azure for enterprise integrations.'],['Account economics & review notes','Client evidence & commercial discussions','Client financials & scenario records'],['Protect the margin behind the revenue','Revenue growth can hide delivery overruns, low effective rates, and unprofitable accounts.','A shared profitability workspace connects revenue with direct costs and the decisions needed to improve the account.','Make client economics visible',['Revenue & labor','Contribution & margin','Account scenarios']],['Profitability copilot',['Identify client margin risks','Draft an account profitability review','Model account-analysis time'],'Illustrative client revenue · direct labor · billable hours','Contribution equals net revenue less direct labor in this sample. Review scope changes, delivery effort, and realized rates before assuming a pricing or staffing action will improve the account.','Account profitability review\nConfirm the reporting period and net revenue. Reconcile delivery labor and billed hours, identify scope or utilization issues, then test a commercial and delivery response with the account owner.',1,'account analyses',30,45],'<path d="M3 20h18M5 16l5-5 4 2 5-8M15 5h4v4"/>');
const impactInputs={hours:120,rate:65,adoption:70,running:72000,build:100000,base:2400000,multiple:6.5};
function impactValues(){const d=impactInputs,gross=d.hours*d.rate*52*d.adoption/100,net=gross-d.running,year=net-d.build,baseline=d.base*d.multiple,scenario=(d.base+net)*d.multiple;return {gross,net,year,baseline,scenario,uplift:scenario-baseline}}
function impactSet(k,v){impactInputs[k]=Number(v);$('#impact-'+k).textContent=['hours','adoption','multiple'].includes(k)?v:money(Number(v));$('#impactResults').innerHTML=impactResults()}
function impactResults(){const v=impactValues();return `<div class="impact-value-grid">${[['Gross capacity value / year',money(v.gross),'Time released × hourly value × adoption'],['Net annual operating benefit',money(v.net),'Gross value less annual running cost'],['Year-one benefit after build',money(v.year),'Net annual benefit less build investment'],['Illustrative enterprise-value change',money(v.uplift),'Net benefit × assumed multiple']].map(([h,x,p])=>`<section><span>${h}</span><b>${x}</b><p>${p}</p></section>`).join('')}</div><div class="impact-comparison"><div><small>Baseline enterprise value</small><strong>${money(v.baseline)}</strong></div><span>→</span><div><small>Illustrative scenario</small><strong>${money(v.scenario)}</strong></div></div><p class="finance-note">Capacity value is not automatically cash savings. The enterprise-value illustration assumes all net capacity value converts to recurring EBITDA, with no change to the multiple. Validate that conversion before using the result.</p>`}
function impactExperience(){return `<div class="experience impact-product">${expHeader(16,ib('AI value review','intelligenceOpen(16,0)','spark','primary'))}<div class="finance-body"><div class="finance-title"><div><span class="micro-label">MEASUREMENT & OPERATING VALUE</span><h1>${tab===0?'Two perspectives. One measurable operating change.':tab===1?'An explicit model of the value assumptions.':'Make the assumptions inspectable.'}</h1><p>A practical framework for discussing operating improvement and enterprise value.</p></div></div>${tab===0?`<div class="impact-thesis"><section><span>01 / OPERATING LIFT</span><h2>Improve the economics of the work.</h2><p>Examine capacity released, quality, revenue contribution, and the recurring costs required to sustain the application.</p></section><section><span>02 / REPEATABLE CAPABILITY</span><h2>Build an operating capability the business can reuse.</h2><p>Consider maintainability, adoption, documentation, and how the workflow could extend across teams. Keep strategic capability separate from quantified financial benefit.</p></section></div><div class="finance-analysis-note"><h2>Start with a baseline. Change the assumptions. Review the evidence.</h2>${ib('Open the value model','tab=1;render()','arrow','primary')}</div>`:tab===1?`<div class="impact-model"><aside>${[['hours','Weekly hours potentially released',0,500,5],['rate','Hourly capacity value · $',20,200,5],['adoption','Adoption · %',0,100,5],['running','Annual running cost · $',0,200000,5000],['build','Build investment · $',0,300000,10000],['multiple','Illustrative EBITDA multiple',3,12,.5]].map(([k,l,min,max,step])=>`<label class="financial-lever"><span>${l}<output id="impact-${k}">${['rate','running','build'].includes(k)?money(impactInputs[k]):impactInputs[k]}</output></span><input type="range" aria-label="${l}" min="${min}" max="${max}" step="${step}" value="${impactInputs[k]}" oninput="impactSet('${k}',this.value)"></label>`).join('')}<p class="finance-note">Baseline EBITDA: ${money(impactInputs.base)}. All inputs are hypothetical.</p></aside><div id="impactResults">${impactResults()}</div></div>`:`${table(['Input','Current assumption','Evidence needed'],[['Hours potentially released',impactInputs.hours+' / week','Task-level baseline and repeated measurement'],['Capacity value',money(impactInputs.rate)+' / hour','Agreed loaded cost or contribution logic'],['Adoption',impactInputs.adoption+'%','Observed user adoption and completed workflows'],['Running cost',money(impactInputs.running)+' / year','Hosting, model usage, support, and administration'],['Valuation multiple',impactInputs.multiple+'×','Comparable evidence and professional valuation review']])}<div class="finance-analysis-note"><h2>Illustration, not an appraisal.</h2><p>No input here is represented as validated client evidence. Results should be reviewed against actual operating data before an investment or valuation decision.</p>${ib('Draft value narrative','intelligenceOpen(16,1)','spark','primary')}</div>`}<p class="finance-note">Sample model · No actual client results represented · Source assumptions remain visible</p></div></div>`}
const profitClients=[['Northstar Manufacturing','Manufacturing','Alex Morgan',460000,310000,3200],['Harbor Financial','Financial services','Taylor Kim',580000,240000,2600],['Cedar Health Partners','Healthcare','Jordan Ellis',320000,350000,3400],['Summit Logistics','Logistics','Alex Morgan',290000,170000,1900],['Meridian Services','Professional services','Taylor Kim',260000,290000,2800],['Oakfield Engineering','Engineering','Jordan Ellis',410000,200000,2300],['Willow Foods','Manufacturing','Alex Morgan',360000,210000,2400],['Beacon Services','Professional services','Jordan Ellis',280000,140000,1800]];
let profitVertical='All',profitOwner='All';
function profitList(){return profitClients.map((c,id)=>({id,name:c[0],vertical:c[1],owner:c[2],revenue:c[3],labor:c[4],hours:c[5],contribution:c[3]-c[4],margin:(c[3]-c[4])/c[3]*100,rate:c[3]/c[5]})).filter(c=>(profitVertical==='All'||c.vertical===profitVertical)&&(profitOwner==='All'||c.owner===profitOwner))}
function profitTotals(){const a=profitList(),revenue=a.reduce((s,c)=>s+c.revenue,0),labor=a.reduce((s,c)=>s+c.labor,0),hours=a.reduce((s,c)=>s+c.hours,0);return {a,revenue,labor,hours,contribution:revenue-labor,margin:revenue?(revenue-labor)/revenue*100:0,rate:hours?revenue/hours:0}}
function profitDetail(id){const c=profitClients[id];draw(c[0]+' · client economics',`<p>${c[1]} · ${c[2]} · Sample six-month period</p><div class="case-financials"><div><small>Net revenue</small><b>${money(c[3])}</b></div><div><small>Contribution</small><b>${money(c[3]-c[4])}</b></div><div><small>Margin</small><b>${((c[3]-c[4])/c[3]*100).toFixed(1)}%</b></div></div><h3>Test an account scenario</h3><label class="health-label">Revenue change · %<input id="profitRevenueChange" type="number" min="-50" max="100" value="0" oninput="profitScenario(${id})"></label><label class="health-label">Direct labor change · %<input id="profitLaborChange" type="number" min="-50" max="100" value="0" oninput="profitScenario(${id})"></label><div id="profitScenarioResult" class="finance-analysis-note"><b>Baseline margin: ${((c[3]-c[4])/c[3]*100).toFixed(1)}%</b><p>Change an assumption to compare it with the baseline.</p></div><p class="finance-note">Contribution = net revenue − direct labor. Excludes overhead and other account costs. Scenarios do not change the source account data.</p>${ib('AI profitability review','intelligenceOpen(17,0)','spark','primary')}`)}
function profitScenario(id){const c=profitClients[id],r=c[3]*(1+Math.max(-50,Math.min(100,Number($('#profitRevenueChange').value)||0))/100),l=c[4]*(1+Math.max(-50,Math.min(100,Number($('#profitLaborChange').value)||0))/100);$('#profitScenarioResult').innerHTML=`<div class="profit-scenario-values"><div><span>Baseline contribution</span><b>${money(c[3]-c[4])}</b></div><div><span>Scenario contribution</span><b>${money(r-l)}</b></div><div><span>Scenario margin</span><b>${((r-l)/r*100).toFixed(1)}%</b></div></div><p>Revenue ${money(r)} · Direct labor ${money(l)} · Change in contribution ${money(r-l-(c[3]-c[4]))}</p>`}
function profitExperience(){const t=profitTotals(),a=tab===1?t.a.filter(c=>c.margin<30):t.a;return `<div class="experience profitability-product">${expHeader(17,ib('AI account analysis','intelligenceOpen(17,0)','spark','primary'))}<div class="finance-body"><div class="finance-title"><div><span class="micro-label">CLIENT PROFITABILITY MANAGEMENT</span><h1>${expMenu[17][tab]}</h1><p>Six-month sample period · Account economics with visible calculation inputs.</p></div><div class="profit-filters"><select aria-label="Business area" onchange="profitVertical=this.value;render()">${['All',...new Set(profitClients.map(c=>c[1]))].map(v=>`<option ${v===profitVertical?'selected':''}>${v}</option>`).join('')}</select><select aria-label="Account owner" onchange="profitOwner=this.value;render()">${['All','Alex Morgan','Taylor Kim','Jordan Ellis'].map(v=>`<option ${v===profitOwner?'selected':''}>${v}</option>`).join('')}</select></div></div>${tab!==2?`<div class="profit-kpis">${[['Net revenue',money(t.revenue),'Sum of selected account revenue'],['Contribution',money(t.contribution),'Net revenue less direct labor'],['Contribution margin',t.margin.toFixed(1)+'%','Contribution ÷ net revenue'],['Direct labor',t.revenue?(t.labor/t.revenue*100).toFixed(1)+'%':'0%','Direct labor ÷ net revenue'],['Effective rate',money(t.rate),'Net revenue ÷ billable hours'],['Unprofitable clients',t.a.filter(c=>c.contribution<0).length,'Negative contribution in sample period'],['Profitable clients',t.a.length?(t.a.filter(c=>c.contribution>0).length/t.a.length*100).toFixed(1)+'%':'0%','Positive contribution accounts'],['Net revenue at loss-making accounts',money(t.a.filter(c=>c.contribution<0).reduce((s,c)=>s+c.revenue,0)),'Revenue, not the amount of loss']].map(([h,v,p])=>`<button onclick="profitExplain('${h}')"><span>${h}</span><b>${v}</b><small>${p}</small></button>`).join('')}</div><h2 class="profit-register-title">${tab===1?'Accounts below 30% contribution margin':'Account economics'}</h2>${a.length?table(['Client','Owner','Net revenue','Direct labor','Contribution','Margin',''],a.map(c=>[c.name,c.owner,money(c.revenue),money(c.labor),money(c.contribution),`<span class="finance-delta ${c.margin<0?'unfavorable':c.margin<30?'neutral':'favorable'}">${c.margin.toFixed(1)}%</span>`,ib('Inspect',`profitDetail(${c.id})`,'arrow','link')])):'<p>No accounts match this watch criterion and the current filters.</p>'}`:`<div class="finance-analysis-note"><h2>Review ${t.a.filter(c=>c.contribution<0).length} loss-making accounts before interpreting portfolio growth.</h2><p>The selected accounts generate ${money(t.revenue)} in revenue and ${money(t.contribution)} in contribution. Their aggregate contribution margin is ${t.margin.toFixed(1)}%.</p><p>Investigate scope, delivery labor, and realized rates at low-margin accounts. This sample excludes overhead, pass-through costs, and other account-level expenses, so contribution is not net profit.</p>${ib('Draft executive commentary','intelligenceOpen(17,1)','spark','primary')}</div>`}<p class="finance-note">Illustrative account data · Contribution excludes overhead · No live financial or project-system connection</p></div></div>`}
function profitExplain(name){const t=profitTotals();draw(name,`<p>These metrics are calculated from ${t.a.length} accounts matching the current filters. Revenue is ${money(t.revenue)}, direct labor is ${money(t.labor)}, and billed hours total ${t.hours.toLocaleString()}.</p><p>Contribution = revenue − direct labor. Contribution margin = contribution ÷ revenue. Effective rate = revenue ÷ billed hours. Unprofitable accounts have negative contribution.</p><p>This sample view does not include overhead allocation, pass-through costs, write-offs, or taxes. It must not be interpreted as net client profit.</p>${ib('Inspect client watch','closeDrawer();tab=1;render()','arrow','primary')}`)}
// Register late-loaded deep links after all application metadata is available.
const financeDeepLink=toolsList.findIndex(t=>t[0].toLowerCase().replaceAll(' ','-')===location.hash.slice(1).split('/')[0]);if(financeDeepLink>=14)current=financeDeepLink;
render();
